import ply.lex as lex
import ply.yacc as yacc
from taf.ul.generic_tshark_json_parser.submodule_ute_common_abstract_core import message_query_tokenizer as tokenizer
from taf.ul.generic_tshark_json_parser.submodule_ute_common_abstract_core import message_query_parser as query_parser
import os
import sys


def message_query_parser():
    """
    Message query builder
    :return:
    """
    _allow_dynamic_files_creation()
    lex.lex(module=tokenizer)
    parser = yacc.yacc(module=query_parser)
    return parser


def _allow_dynamic_files_creation():
    if sys.version_info[0] >= 3:
        ute_common_abstract_core_location = os.sep.join(query_parser.__file__.split(os.sep)[:-1])
        if os.access(ute_common_abstract_core_location, os.W_OK) is False:
            add_proper_rights_cmd = 'sudo chown ute:ute {}'.format(ute_common_abstract_core_location)
            os.system(add_proper_rights_cmd)
    else:
        pass